using System.Globalization;
using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;

/// <summary>Generate a deterministic, self-contained HTML overview from validated retained measurements.</summary>
internal static class Overview
{
    /// <summary>Read from the checkout root; no experiments, downloads or system settings are changed.</summary>
    public static int Main(string[] args)
    {
        try {
            string root=args.Length==0?Directory.GetCurrentDirectory():Path.GetFullPath(args[0]);
            if(!Directory.Exists(root)||!Directory.Exists(Path.Combine(root,"results")))throw new DirectoryNotFoundException("Run from a benchmark checkout.");
            var cells=JsonSerializer.Deserialize(File.ReadAllText(Path.Combine(root,"results/summary.json")),OverviewJson.Default.OverviewCellArray)
                ??throw new InvalidDataException("Missing summary data.");
            OverviewData data=OverviewModel.Build(cells);
            string template=File.ReadAllText(Path.Combine(root,"Overview.template.html"));
            if(template.Split("__DATA__",StringSplitOptions.None).Length!=2)throw new InvalidDataException("Expected exactly one embedded-data placeholder.");
            // Source-generated serialization escapes HTML-sensitive characters and supports Native AOT.
            string html=template.Replace("__DATA__",JsonSerializer.Serialize(data,OverviewJson.Default.OverviewData),StringComparison.Ordinal)
                .Replace("__MEASURED__",data.Measured.ToString("N0",CultureInfo.InvariantCulture),StringComparison.Ordinal)
                .Replace("__WARMUPS__",data.Warmups.ToString("N0",CultureInfo.InvariantCulture),StringComparison.Ordinal);
            File.WriteAllText(Path.Combine(root,"results/overview.html"),html,new UTF8Encoding(false));
            Console.WriteLine($"Overview: {data.Cohorts.Length} cohorts, {data.Measured} measured commands, {data.Warmups} warmups.");return 0;
        }catch(Exception ex){Console.Error.WriteLine(ex.Message);return 1;}
    }
}

[JsonSerializable(typeof(OverviewCell[]))]
[JsonSerializable(typeof(OverviewData))]
internal partial class OverviewJson:JsonSerializerContext;

using System.Runtime.CompilerServices;

[assembly:InternalsVisibleTo("SedBench.Tests")]

/// <summary>One seven-repeat summary; milliseconds are end-to-end wall time, never CPU time.</summary>
internal sealed record OverviewCell(string Task,string Engine,long InputBytes,int N,double Median,double Min,double Max,double Q1,double Q3);
/// <summary>A comparison session. Cells from different sessions must not share a ranking.</summary>
internal sealed record OverviewCohort(string Id,string Title,string Description,int Measured,int Warmups,OverviewCell[] Cells);
/// <summary>Complete embedded dataset, suitable for offline exploration without network dependencies.</summary>
internal sealed record OverviewData(int Measured,int Warmups,OverviewCohort[] Cohorts);

/// <summary>Validate finite measurements and preserve the original nine experimental cohorts.</summary>
internal static class OverviewModel
{
    internal static readonly string[] Tasks=["literal","regex","count","nonblank","replace","field","words","lines","sed-literal","sed-regex","sed-nonblank","sed-select","sed-head","sed-transliterate"];
    static readonly long[] InputSizes=[1071,65580,1048616,8388671,33554436];
    static readonly (string Id,string Title,int Cells,string Description)[] Definitions=[
        ("baseline","GNU & PowerShell",72,"Eight equivalent operations, three file sizes, three approaches: GNU tools, PowerShell pipelines and buffered .NET readers."),
        ("selectstring","Select-String",9,"Three search operations at three large-file sizes. A separate supplemental session; historical GNU timings are not treated as paired controls."),
        ("grep","ripgrep & GNU grep",24,"Four search operations, interleaved fresh processes. This is the direct ripgrep/GNU comparison at 1, 8 and 32 MiB."),
        ("small","Small-file search",30,"Literal, regex and count at about 1 KiB and 64 KiB. Five approaches interleaved; process startup can dominate."),
        ("rawk","Two Rust AWKs",45,"Unmodified release builds of stefanalfbo/rawk and quinnjr/awk-rs against fresh GNU awk, across five input sizes."),
        ("awk","mawk & frawk",45,"mawk, the frawk bytecode interpreter and a fresh GNU awk control. The frawk Cranelift JIT failed and has no successful timing results."),
        ("buffer","Rust stdout buffering",12,"Paired fresh controls versus separate 64 KiB BufWriter variants. Only command-line stdout buffering changed; three 32 MiB operations."),
        ("tuning","GNU grep build flags",60,"Same source/compiler/runtime: generic O2 versus native O3. The installed binary is an additional reference. Ripgrep was not in this session."),
        ("sed","Sed implementations",130,"GNU sed, BusyBox, uutils/sed and red: six operations, five sizes. sd participates in two replacements only. Identical GNU binaries count once.")
    ];

    /// <summary>Reject invalid units, impossible quartiles, unknown operations and incomplete repetition counts.</summary>
    internal static void ValidateCell(OverviewCell cell)
    {
        ArgumentNullException.ThrowIfNull(cell);
        if(string.IsNullOrWhiteSpace(cell.Engine)||!Tasks.Contains(cell.Task,StringComparer.Ordinal)||!InputSizes.Contains(cell.InputBytes)||cell.N!=7)
            throw new InvalidDataException("Invalid operation, identity, input size or repetition count.");
        double[] values=[cell.Min,cell.Q1,cell.Median,cell.Q3,cell.Max];
        if(values.Any(v=>!double.IsFinite(v)||v<=0)||!values.SequenceEqual(values.Order()))
            throw new InvalidDataException("Times must be finite, positive and ordered min/Q1/median/Q3/max.");
    }

    /// <summary>Assign only observed engine/size combinations; an unknown source cannot silently join a comparison.</summary>
    internal static string Assign(OverviewCell cell)
    {
        ValidateCell(cell);bool small=cell.InputBytes<100000;
        return cell.Engine switch {
            "gnu" when !small=>"baseline",
            "pipeline" or "reader"=>small?"small":"baseline",
            "selectstring"=>small?"small":"selectstring",
            "ripgrep" or "grep-current"=>small?"small":"grep",
            "rawk-stefan" or "awk-rs-quinn" or "awk-current"=>"rawk",
            "mawk" or "frawk-interp" or "awk-extra-control"=>"awk",
            "rawk-stefan-control" or "rawk-stefan-buffered" or "awk-rs-quinn-control" or "awk-rs-quinn-buffered"=>"buffer",
            "grep-built-o2" or "grep-native-o3" or "grep-installed-fresh"=>"tuning",
            "sed-gnu" or "sed-busybox" or "sed-uutils" or "sed-red" or "sd"=>"sed",
            _=>throw new InvalidDataException("Unknown experimental cohort.")
        };
    }

    /// <summary>Require all 427 distinct cells, so the overview cannot make a partial campaign look complete.</summary>
    internal static OverviewData Build(OverviewCell[] cells)
    {
        ArgumentNullException.ThrowIfNull(cells);
        if(cells.Length!=427||cells.Select(c=>(c.Task,c.Engine,c.InputBytes)).Distinct().Count()!=cells.Length)
            throw new InvalidDataException("Expected 427 distinct summary cells.");
        var groups=cells.GroupBy(Assign).ToDictionary(g=>g.Key,g=>g.ToArray(),StringComparer.Ordinal);
        var cohorts=new List<OverviewCohort>();
        foreach(var definition in Definitions) {
            if(!groups.TryGetValue(definition.Id,out var members)||members.Length!=definition.Cells)
                throw new InvalidDataException($"Incomplete cohort: {definition.Id}");
            if(members.Any(c=>!Allowed(definition.Id,c)))throw new InvalidDataException("An operation or size does not belong to its recorded cohort.");
            cohorts.Add(new(definition.Id,definition.Title,definition.Description,members.Sum(c=>c.N),members.Length,
                members.OrderBy(c=>c.InputBytes).ThenBy(c=>c.Task,StringComparer.Ordinal).ThenBy(c=>c.Engine,StringComparer.Ordinal).ToArray()));
        }
        return new(cohorts.Sum(c=>c.Measured),cohorts.Sum(c=>c.Warmups),cohorts.ToArray());
    }

    // Counts alone are insufficient: an edited summary could substitute a different
    // valid task while leaving the total unchanged. Preserve the actual task domains.
    static bool Allowed(string id,OverviewCell cell)=>id switch {
        "baseline"=>!cell.Task.StartsWith("sed-",StringComparison.Ordinal)&&cell.InputBytes>=1048616,
        "selectstring"=>cell.Task is "literal" or "regex" or "count"&&cell.InputBytes>=1048616,
        "grep"=>cell.Task is "literal" or "regex" or "count" or "nonblank"&&cell.InputBytes>=1048616,
        "small"=>cell.Task is "literal" or "regex" or "count"&&cell.InputBytes<100000,
        "rawk" or "awk"=>cell.Task is "field" or "words" or "lines",
        "buffer"=>cell.Task is "field" or "words" or "lines"&&cell.InputBytes==33554436,
        "tuning"=>cell.Task is "literal" or "regex" or "count" or "nonblank",
        "sed"=>cell.Task.StartsWith("sed-",StringComparison.Ordinal)&&(cell.Engine!="sd"||cell.Task is "sed-literal" or "sed-regex"),
        _=>false
    };
}

using System.Reflection;
using System.Text.Json;

namespace SedBench.Tests;

/// <summary>Protect units, cohort boundaries and incomplete-data behavior of the overview generator.</summary>
public class OverviewTests
{
    static OverviewCell Valid=>new("literal","gnu",1048616,7,3,1,5,2,4);
    static OverviewCell[] Campaign()
    {
        using var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("overview-summary.json")!;
        return JsonSerializer.Deserialize<OverviewCell[]>(stream)!;
    }

    /// <summary>Validate retained totals, completeness and one-cohort-per-cell assignment.</summary>
    [Test]
    public void CompleteCampaignPreservesAllSessions()
    {
        var result=OverviewModel.Build(Campaign());
        Assert.Multiple(()=>{
            Assert.That(result.Measured,Is.EqualTo(2989));Assert.That(result.Warmups,Is.EqualTo(427));
            Assert.That(result.Cohorts,Has.Length.EqualTo(9));
            Assert.That(result.Cohorts.SelectMany(c=>c.Cells).Count(),Is.EqualTo(427));
            Assert.That(result.Cohorts.Single(c=>c.Id=="grep").Cells.All(c=>c.Engine is "ripgrep" or "grep-current"),Is.True);
            Assert.That(result.Cohorts.Single(c=>c.Id=="tuning").Cells.Any(c=>c.Engine=="ripgrep"),Is.False);
        });
    }

    /// <summary>Reject incomplete, duplicate and unknown-session input rather than silently publishing partial results.</summary>
    [Test]
    public void CorruptedCampaignFailsClosed()
    {
        var cells=Campaign();Assert.That(()=>OverviewModel.Build(cells[..^1]),Throws.TypeOf<InvalidDataException>());
        cells[0]=cells[1];Assert.That(()=>OverviewModel.Build(cells),Throws.TypeOf<InvalidDataException>());
        cells=Campaign();var sameSession=Enumerable.Range(0,cells.Length).Where(i=>OverviewModel.Assign(cells[i])=="tuning").Take(2).ToArray();
        cells[sameSession[0]]=cells[sameSession[1]];Assert.That(()=>OverviewModel.Build(cells),Throws.TypeOf<InvalidDataException>());
        cells=Campaign();cells[0]=cells[0] with{Engine="unknown"};Assert.That(()=>OverviewModel.Build(cells),Throws.TypeOf<InvalidDataException>());
        cells=Campaign();cells[0]=cells[0] with{Engine="grep-built-o2",InputBytes=1234567};Assert.That(()=>OverviewModel.Build(cells),Throws.TypeOf<InvalidDataException>());
        cells=Campaign();int index=Array.FindIndex(cells,c=>c.Engine=="sed-gnu");cells[index]=cells[index] with{Task="field"};Assert.That(()=>OverviewModel.Build(cells),Throws.TypeOf<InvalidDataException>());
        cells=Campaign();for(int i=0;i<cells.Length;i++)if(cells[i].Engine=="selectstring"&&cells[i].InputBytes>=1048616)cells[i]=cells[i] with{Engine="sed-red"};
        Assert.That(()=>OverviewModel.Build(cells),Throws.TypeOf<InvalidDataException>());
        cells=Campaign();index=Array.FindIndex(cells,c=>OverviewModel.Assign(c)=="buffer");cells[index]=cells[index] with{InputBytes=1071};
        Assert.That(()=>OverviewModel.Build(cells),Throws.TypeOf<InvalidDataException>());
        Assert.That(()=>OverviewModel.Build(null!),Throws.ArgumentNullException);
    }

    /// <summary>Separate reused engine names by input-size cohort; fresh controls have explicit identities.</summary>
    [TestCase("grep-current",33554436,"grep")][TestCase("grep-current",65580,"small")]
    [TestCase("ripgrep",33554436,"grep")][TestCase("ripgrep",1071,"small")]
    [TestCase("pipeline",1048616,"baseline")][TestCase("reader",65580,"small")]
    [TestCase("selectstring",1048616,"selectstring")][TestCase("selectstring",1071,"small")]
    [TestCase("awk-current",33554436,"rawk")][TestCase("awk-extra-control",33554436,"awk")]
    [TestCase("rawk-stefan-control",33554436,"buffer")][TestCase("sed-uutils",33554436,"sed")]
    public void CohortBoundaries(string engine,long bytes,string expected)=>Assert.That(OverviewModel.Assign(Valid with{Engine=engine,InputBytes=bytes}),Is.EqualTo(expected));

    /// <summary>Valid global operations cannot be substituted into a session that never measured them.</summary>
    [TestCase("baseline","sed-head")][TestCase("selectstring","words")][TestCase("grep","field")]
    [TestCase("small","field")][TestCase("buffer","literal")]
    public void WrongOperationCannotMasqueradeAsACompleteCohort(string cohort,string task)
    {
        var cells=Campaign();int index=Array.FindIndex(cells,c=>OverviewModel.Assign(c)==cohort);
        cells[index]=cells[index] with{Task=task};
        Assert.That(()=>OverviewModel.Build(cells),Throws.TypeOf<InvalidDataException>());
    }

    /// <summary>Malformed identities, counts, units, NaN/infinity and quartile inversions are invalid.</summary>
    [Test]
    public void InvalidCellsAreRejected()
    {
        foreach(var cell in new[]{Valid with{Engine=" "},Valid with{Task="unknown"},Valid with{InputBytes=0},Valid with{InputBytes=-1},Valid with{N=6},Valid with{Median=double.NaN},Valid with{Max=double.PositiveInfinity},Valid with{Min=0},Valid with{Q1=4},Valid with{Q3=2}})
            Assert.That(()=>OverviewModel.ValidateCell(cell),Throws.TypeOf<InvalidDataException>());
        Assert.That(()=>OverviewModel.ValidateCell(null!),Throws.ArgumentNullException);
    }

    /// <summary>Seeded valid order statistics, including equal-valued samples, remain accepted.</summary>
    [Test]
    public void SeededValidSummaries()
    {
        var random=new Random(20261026);
        for(int i=0;i<500;i++) {
            double[] v=Enumerable.Range(0,7).Select(_=>1+random.NextDouble()*1000).Order().ToArray();
            var cell=Valid with{Min=v[0],Q1=v[1],Median=v[3],Q3=v[5],Max=v[6]};
            Assert.That(()=>OverviewModel.ValidateCell(cell),Throws.Nothing,$"seed 20261026 case {i}");
        }
        Assert.That(()=>OverviewModel.ValidateCell(Valid with{Min=1,Q1=1,Median=1,Q3=1,Max=1}),Throws.Nothing);
    }

    /// <summary>Malformed JSON/templates and absent directories fail without publishing a replacement page.</summary>
    [Test]
    public void GeneratorRejectsMalformedInputsAndWritesDeterministically()
    {
        string parent=Path.GetTempPath();Assert.That(Directory.Exists(parent),Is.True);
        string root=Path.Combine(parent,"TextToolBench-overview-"+Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        try {
            Assert.That(global::Overview.Main([Path.Combine(root,"missing")]),Is.EqualTo(1));
            string results=Path.Combine(root,"results");Directory.CreateDirectory(results);
            Assert.That(global::Overview.Main([root]),Is.EqualTo(1));
            string summary=Path.Combine(results,"summary.json");File.WriteAllText(summary,"{broken");
            Assert.That(global::Overview.Main([root]),Is.EqualTo(1));
            File.WriteAllText(summary,"null");Assert.That(global::Overview.Main([root]),Is.EqualTo(1));
            File.WriteAllText(summary,JsonSerializer.Serialize(Campaign()));
            File.WriteAllText(Path.Combine(root,"Overview.template.html"),"__DATA__ __DATA__");
            Assert.That(global::Overview.Main([root]),Is.EqualTo(1));
            Assert.That(File.Exists(Path.Combine(results,"overview.html")),Is.False);
            File.WriteAllText(Path.Combine(root,"Overview.template.html"),"<!doctype html>__DATA__ __MEASURED__ __WARMUPS__");
            Assert.That(global::Overview.Main([root]),Is.Zero);
            byte[] first=File.ReadAllBytes(Path.Combine(results,"overview.html"));
            Assert.That(global::Overview.Main([root]),Is.Zero);
            Assert.That(File.ReadAllBytes(Path.Combine(results,"overview.html")),Is.EqualTo(first));
        }finally{
            // Only this test's newly created GUID directory is eligible for removal.
            if(Path.GetFullPath(root).StartsWith(Path.GetFullPath(parent),StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(root).StartsWith("TextToolBench-overview-",StringComparison.Ordinal))Directory.Delete(root,true);
        }
    }
}

namespace SedBench.Tests;

/// <summary>Independent examples and seeded properties for the byte reference, not timing assertions.</summary>
public class Tests
{
    /// <summary>Challenge case, digit groups, record selection and missing terminators.</summary>
    [TestCase("sed-literal","Prince PrincePrince prince\n","PRINCE PRINCEPRINCE prince\n")]
    [TestCase("sed-regex","12x0 456\n7","#x# #\n#")]
    [TestCase("sed-regex","no digits\n","no digits\n")]
    [TestCase("sed-nonblank","\n \t\nword\n\r\n","word\n\r\n")]
    [TestCase("sed-nonblank"," \t","")]
    [TestCase("sed-nonblank","word","word")]
    [TestCase("sed-select","prince\nPrince\nPrince","Prince\nPrince")]
    [TestCase("sed-select","other\n","")]
    [TestCase("sed-transliterate","aeiou AEIOU y\r\n","AEIOU AEIOU y\r\n")]
    [TestCase("sed-head","","")]
    public void Examples(string task,string input,string expected)=>Assert.That(SedSemantics.Transform(System.Text.Encoding.Latin1.GetBytes(input),task),Is.EqualTo(System.Text.Encoding.Latin1.GetBytes(expected)));

    /// <summary>Check either side of the 100-record boundary, with and without a final LF.</summary>
    [TestCase(0,true)][TestCase(1,true)][TestCase(99,true)][TestCase(100,true)][TestCase(101,true)][TestCase(250,true)]
    [TestCase(0,false)][TestCase(1,false)][TestCase(99,false)][TestCase(100,false)][TestCase(101,false)][TestCase(250,false)]
    public void HeadBoundary(int records,bool finalLf)
    {
        string input=string.Join('\n',Enumerable.Range(1,records).Select(i=>i.ToString()));if(records>0&&finalLf)input+='\n';
        string expected=string.Join('\n',Enumerable.Range(1,Math.Min(records,100)).Select(i=>i.ToString()));
        if(records>0&&(finalLf||records>100))expected+='\n';
        Assert.That(SedSemantics.Transform(System.Text.Encoding.ASCII.GetBytes(input),"sed-head"),Is.EqualTo(System.Text.Encoding.ASCII.GetBytes(expected)));
    }

    /// <summary>Each transformation is a projection; arbitrary binary input stays byte-representable.</summary>
    [Test]
    public void SeededByteProperties()
    {
        var random=new Random(20261107);
        foreach(string task in new[]{"sed-literal","sed-regex","sed-nonblank","sed-select","sed-head","sed-transliterate"})
            for(int i=0;i<200;i++) {
                byte[] input=new byte[random.Next(0,4097)];random.NextBytes(input);
                byte[] once=SedSemantics.Transform(input,task);
                Assert.That(SedSemantics.Transform(once,task),Is.EqualTo(once),$"seed 20261107, case {i}, {task}");
            }
        byte[] binary=[0,255,128,80,114,105,110,99,101,13,10];
        Assert.That(SedSemantics.Transform(binary,"sed-literal"),Is.EqualTo(new byte[]{0,255,128,80,82,73,78,67,69,13,10}));
    }

    /// <summary>Unsupported identifiers must fail explicitly, even on empty input.</summary>
    [Test]
    public void UnknownTaskIsRejected()=>Assert.That(()=>SedSemantics.Transform([],"unknown"),Throws.ArgumentException);
}
